SELECT COUNT(DISTINCT t.POID) AS distinct_entity_cnt FROM ods_klerp.efi_cms_zp0fiaif0017s t WHERE t.POID IS NOT NULL;
SELECT t.POID, COUNT(*) AS event_cnt FROM ods_klerp.efi_cms_zp0fiaif0017s t WHERE t.POID IS NOT NULL AND t.CONTRACTID IS NOT NULL GROUP BY t.POID ORDER BY event_cnt DESC LIMIT 1000;
SELECT COUNT(*) AS event_cnt FROM ods_klerp.efi_cms_zp0fiaif0017s t WHERE STR_TO_DATE(CAST(t.ERDAT AS CHAR), '%Y%m%d') >= '2024-01-01' AND STR_TO_DATE(CAST(t.ERDAT AS CHAR), '%Y%m%d') < '2024-01-31';
SELECT t.A_OBJECTSSUMTYPE, COUNT(*) AS event_cnt FROM ods_klerp.efi_cms_zp0fiaif0017s t WHERE t.A_OBJECTSSUMTYPE IS NOT NULL GROUP BY t.A_OBJECTSSUMTYPE ORDER BY event_cnt DESC LIMIT 1000;
SELECT t.A_OBJECTSSUMTYPE, SUM(t.A_OBJECTSSUM) AS total_amount FROM ods_klerp.efi_cms_zp0fiaif0017s t WHERE t.A_OBJECTSSUMTYPE IS NOT NULL AND t.A_OBJECTSSUM IS NOT NULL GROUP BY t.A_OBJECTSSUMTYPE ORDER BY total_amount DESC LIMIT 1000;
SELECT t.CONTRACTID, COUNT(DISTINCT t.POID) AS entity_cnt FROM ods_klerp.efi_cms_zp0fiaif0017s t WHERE t.CONTRACTID IS NOT NULL GROUP BY t.CONTRACTID HAVING COUNT(DISTINCT t.POID) > 1 ORDER BY entity_cnt DESC LIMIT 3;
WITH a AS ( SELECT DISTINCT t.POID FROM ods_klerp.efi_cms_zp0fiaif0017s t WHERE t.POID IS NOT NULL AND STR_TO_DATE(CAST(t.ERDAT AS CHAR), '%Y%m%d') >= '2025-01-01' AND STR_TO_DATE(CAST(t.ERDAT AS CHAR), '%Y%m%d') < '2025-04-01' ), b AS ( SELECT DISTINCT t.POID FROM ods_klerp.efi_cms_zp0fiaif0017s t WHERE t.POID IS NOT NULL AND STR_TO_DATE(CAST(t.ERDAT AS CHAR), '%Y%m%d') >= '2025-10-01' AND STR_TO_DATE(CAST(t.ERDAT AS CHAR), '%Y%m%d') < '2026-01-01' ) SELECT COUNT(*) AS retained_entity_cnt FROM a JOIN b USING (POID);
SELECT t.A_OBJECTSSUMTYPE, SUM(CASE WHEN STR_TO_DATE(CAST(t.ERDAT AS CHAR), '%Y%m%d') >= '2025-01-01' AND STR_TO_DATE(CAST(t.ERDAT AS CHAR), '%Y%m%d') < '2025-04-01' THEN 1 ELSE 0 END) AS curr_cnt, SUM(CASE WHEN STR_TO_DATE(CAST(t.ERDAT AS CHAR), '%Y%m%d') >= '2025-10-01' AND STR_TO_DATE(CAST(t.ERDAT AS CHAR), '%Y%m%d') < '2026-01-01' THEN 1 ELSE 0 END) AS prev_cnt, ( SUM(CASE WHEN STR_TO_DATE(CAST(t.ERDAT AS CHAR), '%Y%m%d') >= '2025-01-01' AND STR_TO_DATE(CAST(t.ERDAT AS CHAR), '%Y%m%d') < '2025-04-01' THEN 1 ELSE 0 END) - SUM(CASE WHEN STR_TO_DATE(CAST(t.ERDAT AS CHAR), '%Y%m%d') >= '2025-10-01' AND STR_TO_DATE(CAST(t.ERDAT AS CHAR), '%Y%m%d') < '2026-01-01' THEN 1 ELSE 0 END) ) AS delta_cnt FROM ods_klerp.efi_cms_zp0fiaif0017s t WHERE t.A_OBJECTSSUMTYPE IS NOT NULL GROUP BY t.A_OBJECTSSUMTYPE ORDER BY delta_cnt DESC LIMIT 3;
WITH daily AS ( SELECT STR_TO_DATE(CAST(t.ERDAT AS CHAR), '%Y%m%d') AS d, COUNT(*) AS cnt FROM ods_klerp.efi_cms_zp0fiaif0017s t WHERE STR_TO_DATE(CAST(t.ERDAT AS CHAR), '%Y%m%d') >= '2025-01-01' AND STR_TO_DATE(CAST(t.ERDAT AS CHAR), '%Y%m%d') < '2025-04-01' GROUP BY STR_TO_DATE(CAST(t.ERDAT AS CHAR), '%Y%m%d') ), ma AS ( SELECT d, cnt, AVG(cnt) OVER (ORDER BY d ROWS BETWEEN 7 PRECEDING AND 1 PRECEDING) AS prev_7d_avg FROM daily ) SELECT d, cnt, prev_7d_avg FROM ma WHERE prev_7d_avg IS NOT NULL AND cnt > prev_7d_avg ORDER BY (cnt - prev_7d_avg) DESC;
WITH daily AS ( SELECT STR_TO_DATE(CAST(t.ERDAT AS CHAR), '%Y%m%d') AS d, COUNT(*) AS cnt FROM ods_klerp.efi_cms_zp0fiaif0017s t WHERE STR_TO_DATE(CAST(t.ERDAT AS CHAR), '%Y%m%d') >= '2025-01-01' AND STR_TO_DATE(CAST(t.ERDAT AS CHAR), '%Y%m%d') < '2025-04-01' GROUP BY STR_TO_DATE(CAST(t.ERDAT AS CHAR), '%Y%m%d') ), ma AS ( SELECT d, cnt, AVG(cnt) OVER (ORDER BY d ROWS BETWEEN 7 PRECEDING AND 1 PRECEDING) AS prev_7d_avg FROM daily ) SELECT d, cnt, prev_7d_avg FROM ma WHERE prev_7d_avg IS NOT NULL AND cnt > prev_7d_avg ORDER BY (cnt - prev_7d_avg) DESC LIMIT 3;
SELECT c.OID, COUNT(DISTINCT c.CODE) AS external_cnt FROM ods_klerp.d1_customer c GROUP BY c.OID HAVING COUNT(DISTINCT c.CODE) > 1 ORDER BY external_cnt DESC LIMIT 10;
SELECT a.CODE AS id_external FROM ods_klerp.d1_account a WHERE COALESCE(a.NOTES, '') LIKE '%ZZ%' or '%JR%' or '%LH%' LIMIT 5;
WITH agg AS ( SELECT t.A_OBJECTSSUMTYPE AS topic, t.A_OBJECTSSUMTYPENAME AS entity_name, SUM(t.A_OBJECTSSUM) AS amt FROM ods_klerp.efi_cms_zp0fiaif0017s t WHERE t.A_OBJECTSSUMTYPE IS NOT NULL AND t.A_OBJECTSSUMTYPENAME IS NOT NULL GROUP BY t.A_OBJECTSSUMTYPE, t.A_OBJECTSSUMTYPENAME ), ranked AS ( SELECT *, ROW_NUMBER() OVER (PARTITION BY topic ORDER BY amt DESC, entity_name) AS rn FROM agg ) SELECT topic, entity_name, amt FROM ranked WHERE rn = 1 ORDER BY amt DESC;
SELECT COUNT(DISTINCT t.PROJECTID) AS distinct_entity_cnt FROM ods_pomp.sec_tempcontract t WHERE t.PROJECTID IS NOT NULL;
SELECT t.PROJECTID, COUNT(*) AS event_cnt FROM ods_pomp.sec_tempcontract t WHERE t.PROJECTID IS NOT NULL AND t.CONTRACTCODE IS NOT NULL GROUP BY t.PROJECTID ORDER BY event_cnt DESC LIMIT 1000;
SELECT COUNT(*) AS event_cnt FROM ods_pomp.bus_baseinfo_fld t WHERE t.XSLXFQDATE >= '2024-01-01 00:00:00' AND t.XSLXFQDATE < '2024-01-31 23:59:59';
SELECT t.CURRENCY, COUNT(*) AS event_cnt FROM ods_pomp.sec_tempcontract t WHERE t.CURRENCY IS NOT NULL GROUP BY t.CURRENCY ORDER BY event_cnt DESC LIMIT 1000;
SELECT t.CURRENCY, SUM(t.TOTALMONEY) AS total_amount FROM ods_pomp.sec_tempcontract t WHERE t.CURRENCY IS NOT NULL AND t.TOTALMONEY IS NOT NULL GROUP BY t.CURRENCY ORDER BY total_amount DESC LIMIT 1000;
SELECT t.CONTRACTCODE, COUNT(DISTINCT t.PROJECTID) AS entity_cnt FROM ods_pomp.sec_tempcontract t WHERE t.CONTRACTCODE IS NOT NULL GROUP BY t.CONTRACTCODE HAVING COUNT(DISTINCT t.PROJECTID) > 1 ORDER BY entity_cnt DESC LIMIT 3;
WITH a AS ( SELECT DISTINCT t.OBJID FROM ods_pomp.bus_baseinfo_fld t WHERE t.OBJID IS NOT NULL AND t.XSLXFQDATE >= '2020-01-01 00:00:00' AND t.XSLXFQDATE < '2020-04-01 00:00:00' ), b AS ( SELECT DISTINCT t.OBJID FROM ods_pomp.bus_baseinfo_fld t WHERE t.OBJID IS NOT NULL AND t.XSLXFQDATE >= '2020-10-01 00:00:00' AND t.XSLXFQDATE < '2021-01-01 00:00:00' ) SELECT COUNT(*) AS retained_entity_cnt FROM a JOIN b USING (OBJID);
WITH agg AS ( SELECT t.OBJID AS topic, SUM(t.HSJE) AS amt FROM ods_pomp.bus_baseinfo_fld t WHERE t.XSLXFQDATE >= '2020-01-01 00:00:00' AND t.XSLXFQDATE < '2020-04-01 00:00:00' AND t.OBJID IS NOT NULL AND t.HSJE IS NOT NULL GROUP BY t.OBJID ), tot AS ( SELECT SUM(amt) AS total_amt FROM agg ) SELECT topic, amt, amt / NULLIF((SELECT total_amt FROM tot), 0) AS amt_share FROM agg ORDER BY amt_share DESC;
WITH daily AS ( SELECT DATE( t.XSLXFQDATE) AS d, COUNT(*) AS cnt FROM ods_pomp.bus_baseinfo_fld t WHERE CAST(t.XSLXFQDATE AS DATETIME) >= '2021-01-01 00:00:00' AND CAST(t.XSLXFQDATE AS DATETIME) < '2021-04-01 00:00:00' GROUP BY d ), ma AS ( SELECT d, cnt, AVG(cnt) OVER (ORDER BY d ROWS BETWEEN 7 PRECEDING AND 1 PRECEDING) AS prev_7d_avg FROM daily ) SELECT d, cnt, prev_7d_avg FROM ma WHERE prev_7d_avg IS NOT NULL AND cnt > prev_7d_avg ORDER BY (cnt - prev_7d_avg) DESC;
SELECT c.IID, COUNT(DISTINCT c.SCODE) AS external_cnt FROM ods_pomp.cus_baseinfo c GROUP BY c.IID HAVING COUNT(DISTINCT c.SCODE) > 1 ORDER BY external_cnt DESC LIMIT 10;
SELECT t.CRMID AS id_external FROM ods_pomp.bus_baseinfo_fld t WHERE COALESCE(t.MOREINFO, '') LIKE '%客户%' or '%产品线%' or '%特殊商务条款线索%' LIMIT 5;
WITH agg AS ( SELECT t.CURRENCY AS topic, t.PROJECTNAME AS entity_name, SUM(t.TOTALMONEY) AS amt FROM ods_pomp.sec_tempcontract t WHERE t.CURRENCY IS NOT NULL AND t.PROJECTNAME IS NOT NULL AND t.TOTALMONEY IS NOT NULL GROUP BY t.CURRENCY, t.PROJECTNAME ), ranked AS ( SELECT *, ROW_NUMBER() OVER (PARTITION BY topic ORDER BY amt DESC, entity_name) AS rn FROM agg ) SELECT topic, entity_name, amt FROM ranked WHERE rn = 1 ORDER BY amt DESC;
SELECT t.OBJID AS category_topic, COUNT(*) AS event_cnt FROM ods_pomp.bus_baseinfo_fld t WHERE str_to_date(t.XSLXFQDATE, '%Y-%m-%d') >= '2020-01-01' AND str_to_date(t.XSLXFQDATE, '%Y-%m-%d') < '2026-01-01' AND COALESCE(t.MOREINFO, '') LIKE '%新产品%' GROUP BY t.OBJID ORDER BY event_cnt DESC LIMIT 10;
SELECT COUNT(DISTINCT t.UNIT_ID) AS distinct_entity_cnt FROM Refinery.node_information t WHERE t.UNIT_ID IS NOT NULL;
SELECT t.UNIT_ID, COUNT(*) AS event_cnt FROM Refinery.node_information t WHERE t.UNIT_ID IS NOT NULL AND t.NODE_ID IS NOT NULL GROUP BY t.UNIT_ID ORDER BY event_cnt DESC LIMIT 1000;
SELECT COUNT(*) AS event_cnt FROM Refinery.balance_information t WHERE t.begin_shift_time >= '2024-01-01 00:00:00' AND t.begin_shift_time < '2024-01-31 23:59:59';
SELECT t.page_type, COUNT(*) AS event_cnt FROM Refinery.balance_information t WHERE t.page_type IS NOT NULL GROUP BY t.page_type ORDER BY event_cnt DESC LIMIT 1000;
SELECT t.page_type, SUM(t.amount) AS total_amount FROM Refinery.balance_information t WHERE t.page_type IS NOT NULL AND t.amount IS NOT NULL GROUP BY t.page_type ORDER BY total_amount DESC LIMIT 1000;
SELECT t.NODE_ID, COUNT(DISTINCT t.page_type) AS entity_cnt FROM Refinery.balance_information t WHERE t.NODE_ID IS NOT NULL GROUP BY t.NODE_ID HAVING COUNT(DISTINCT t.page_type) > 1 ORDER BY entity_cnt DESC LIMIT 3;
WITH a AS ( SELECT DISTINCT t.NODE_ID FROM Refinery.balance_information t WHERE t.NODE_ID IS NOT NULL AND t.begin_shift_time >= '2023-04-01 00:00:00' AND t.begin_shift_time < '2023-04-04 00:00:00' ), b AS ( SELECT DISTINCT t.NODE_ID FROM Refinery.balance_information t WHERE t.NODE_ID IS NOT NULL AND t.begin_shift_time >= '2023-04-06 00:00:00' AND t.begin_shift_time < '2023-04-08 00:00:00' ) SELECT COUNT(*) AS retained_entity_cnt FROM a JOIN b USING (NODE_ID);
SELECT t.page_type, SUM(CASE WHEN t.begin_shift_time >= '2023-04-01 00:00:00' AND t.begin_shift_time < '2023-04-04 00:00:00' THEN 1 ELSE 0 END) AS curr_cnt, SUM(CASE WHEN t.begin_shift_time >= '2023-04-06 00:00:00' AND t.begin_shift_time < '2023-04-08 00:00:00' THEN 1 ELSE 0 END) AS prev_cnt, ( SUM(CASE WHEN t.begin_shift_time >= '2023-04-01 00:00:00' AND t.begin_shift_time < '2023-04-04 00:00:00' THEN 1 ELSE 0 END) - SUM(CASE WHEN t.begin_shift_time >= '2023-04-06 00:00:00' AND t.begin_shift_time < '2023-04-08 00:00:00' THEN 1 ELSE 0 END) ) AS delta_cnt FROM Refinery.balance_information t WHERE t.page_type IS NOT NULL GROUP BY t.page_type ORDER BY delta_cnt DESC LIMIT 3;
WITH agg AS ( SELECT t.page_type AS topic, SUM(t.amount) AS amt FROM Refinery.balance_information t WHERE t.begin_shift_time >= '2023-04-01 00:00:00' AND t.begin_shift_time < '2023-04-04 00:00:00' AND t.page_type IS NOT NULL GROUP BY t.page_type ), tot AS ( SELECT SUM(amt) AS total_amt FROM agg ) SELECT topic, amt, amt / NULLIF((SELECT total_amt FROM tot), 0) AS amt_share FROM agg ORDER BY amt_share DESC;
WITH daily AS ( SELECT DATE( t.begin_shift_time) AS d, COUNT(*) AS cnt FROM Refinery.balance_information t WHERE t.begin_shift_time >= '2023-04-01 00:00:00' AND t.begin_shift_time < '2023-04-04 00:00:00' GROUP BY d ), ma AS ( SELECT d, cnt, AVG(cnt) OVER (ORDER BY d ROWS BETWEEN 7 PRECEDING AND 1 PRECEDING) AS prev_7d_avg FROM daily ) SELECT d, cnt, prev_7d_avg FROM ma WHERE prev_7d_avg IS NOT NULL AND cnt > prev_7d_avg ORDER BY (cnt - prev_7d_avg) DESC LIMIT 3;
SELECT t.node_code, SUM(CASE WHEN t.inout_type = '1' THEN 1 ELSE 0 END) AS hit_cnt, COUNT(*) AS total_cnt, SUM(CASE WHEN t.inout_type = '1' THEN 1 ELSE 0 END) / COUNT(*) AS hit_ratio FROM Refinery.rpt_t_daily_refinery_unit t WHERE t.node_code IS NOT NULL GROUP BY t.node_code HAVING COUNT(*) >= 50 ORDER BY hit_ratio DESC LIMIT 3;
SELECT t.UNIT_ID, COUNT(DISTINCT t.UNIT_CODE) AS external_cnt FROM Refinery.pm_unit_t t GROUP BY t.UNIT_ID HAVING COUNT(DISTINCT t.UNIT_CODE) > 1 ORDER BY external_cnt DESC LIMIT 10;
WITH ranked AS ( SELECT t.UNIT_TYPE_ID AS topic, t.UNIT_NAME AS entity_name, t.CAPACITY AS qty, ROW_NUMBER() OVER (PARTITION BY t.UNIT_TYPE_ID ORDER BY t.CAPACITY DESC, t.UNIT_NAME) AS rn FROM Refinery.pm_unit_t t WHERE t.UNIT_TYPE_ID IS NOT NULL AND t.UNIT_NAME IS NOT NULL AND t.CAPACITY IS NOT NULL ) SELECT topic, entity_name, qty FROM ranked WHERE rn = 1 ORDER BY qty DESC;
SELECT COUNT(DISTINCT ct.start_station_id) AS distinct_entity_cnt FROM NEW_YORK_PLUS.NEW_YORK_CITIBIKE_CITIBIKE_TRIPS ct;
SELECT t.route_id, COUNT(*) AS event_cnt FROM NEW_YORK_PLUS.NEW_YORK_SUBWAY_TRIPS t GROUP BY t.route_id ORDER BY event_cnt DESC LIMIT 1000;
SELECT COUNT(*) AS event_cnt FROM NEW_YORK_PLUS.NEW_YORK_TAXI_TRIPS_TLC_YELLOW_TRIPS_2022 t WHERE FROM_UNIXTIME(t.pickup_datetime / 1000000) >= '2024-01-01 00:00:00' AND FROM_UNIXTIME(t.pickup_datetime / 1000000) < '2024-01-31 23:59:59';
SELECT sr.complaint_type, COUNT(*) AS event_cnt FROM NEW_YORK_PLUS.NEW_YORK_311__311_SERVICE_REQUESTS sr GROUP BY sr.complaint_type ORDER BY event_cnt DESC LIMIT 1000;
SELECT t.payment_type, SUM(t.total_amount) AS total_amount FROM NEW_YORK_PLUS.NEW_YORK_TAXI_TRIPS_TLC_YELLOW_TRIPS_2022 t GROUP BY t.payment_type ORDER BY total_amount DESC LIMIT 1000;
SELECT t.trip_id, COUNT(DISTINCT t.route_id) AS entity_cnt FROM NEW_YORK_PLUS.new_york_subway_trips t GROUP BY t.trip_id HAVING COUNT(DISTINCT t.route_id) > 1 ORDER BY entity_cnt DESC LIMIT 3;
WITH a AS ( SELECT DISTINCT ct.start_station_id FROM NEW_YORK_PLUS.new_york_citibike_citibike_trips ct WHERE FROM_UNIXTIME(ct.starttime / 1000000) >= '2018-06-01 00:00:00' AND FROM_UNIXTIME(ct.starttime / 1000000) < '2018-06-03 00:00:00' ), b AS ( SELECT DISTINCT ct.start_station_id FROM NEW_YORK_PLUS.new_york_citibike_citibike_trips ct WHERE FROM_UNIXTIME(ct.starttime / 1000000) >= '2018-07-01 00:00:00' AND FROM_UNIXTIME(ct.starttime / 1000000) < '2018-07-03 00:00:00' ) SELECT COUNT(*) AS retained_entity_cnt FROM a JOIN b USING (start_station_id);
WITH agg AS ( SELECT t.payment_type AS topic, SUM(t.total_amount) AS amt FROM NEW_YORK_PLUS.new_york_taxi_trips_tlc_yellow_trips_2022 t WHERE FROM_UNIXTIME(t.pickup_datetime / 1000000) >= '2022-09-01 00:00:00' AND FROM_UNIXTIME(t.pickup_datetime / 1000000) < '2022-10-01 00:00:00' GROUP BY t.payment_type ), tot AS ( SELECT SUM(amt) AS total_amt FROM agg ) SELECT topic, amt, amt / NULLIF((SELECT total_amt FROM tot), 0) AS amt_share FROM agg ORDER BY amt_share DESC;
WITH daily AS ( SELECT DATE( FROM_UNIXTIME(t.pickup_datetime / 1000000)) AS d, COUNT(*) AS cnt FROM NEW_YORK_PLUS.new_york_taxi_trips_tlc_yellow_trips_2022 t WHERE FROM_UNIXTIME(t.pickup_datetime / 1000000) >= '2022-09-01 00:00:00' AND FROM_UNIXTIME(t.pickup_datetime / 1000000) < '2022-09-03 00:00:00' GROUP BY d ), ma AS ( SELECT d, cnt, AVG(cnt) OVER (ORDER BY d ROWS BETWEEN 7 PRECEDING AND 1 PRECEDING) AS prev_7d_avg FROM daily ) SELECT d, cnt, prev_7d_avg FROM ma WHERE prev_7d_avg IS NOT NULL AND cnt > prev_7d_avg ORDER BY (cnt - prev_7d_avg) DESC;
SELECT t.tree_id, COUNT(DISTINCT t.block_id) AS external_cnt FROM NEW_YORK_PLUS.NEW_YORK_TREES_TREE_CENSUS_2015 t GROUP BY t.tree_id HAVING COUNT(DISTINCT t.block_id) > 1 ORDER BY external_cnt DESC LIMIT 10;
SELECT sr.unique_key AS id_external FROM NEW_YORK_PLUS.NEW_YORK_311__311_SERVICE_REQUESTS sr WHERE COALESCE(sr.resolution_description, '') LIKE '%inspected%' or '%duplicate%' or '%repaired%' LIMIT 5;
WITH agg AS ( SELECT t.user_type AS topic, t.spc_common AS entity_name, COUNT(*) AS qty FROM NEW_YORK_PLUS.NEW_YORK_TREES_TREE_CENSUS_2015 t WHERE t.spc_common IS NOT NULL GROUP BY t.user_type, t.spc_common ), ranked AS ( SELECT *, ROW_NUMBER() OVER (PARTITION BY topic ORDER BY qty DESC, entity_name) AS rn FROM agg ) SELECT topic, entity_name, qty FROM ranked WHERE rn = 1 ORDER BY qty DESC;
SELECT sr.borough AS location, sr.complaint_type AS category_topic, COUNT(*) AS event_cnt FROM NEW_YORK_PLUS.NEW_YORK_311__311_SERVICE_REQUESTS sr GROUP BY sr.borough, sr.complaint_type HAVING COUNT(*) >= 10 ORDER BY event_cnt DESC LIMIT 20;
SELECT h_rank, COUNT(DISTINCT game_id) AS entity_cnt FROM NCAA_INSIGHTS.NCAA_MBB_GAMES_SR GROUP BY h_rank ORDER BY entity_cnt DESC LIMIT 10;
SELECT game_id, two_points_pct FROM NCAA_INSIGHTS.NCAA_MBB_PLAYERS_GAMES_SR WHERE two_points_pct >= 50 ORDER BY two_points_pct DESC LIMIT 10;
SELECT SUM(h_points * h_two_points_pct / 100.0) AS weighted_amount, SUM(h_points) AS total_amount FROM NCAA_INSIGHTS.NCAA_MBB_GAMES_SR WHERE h_points IS NOT NULL AND h_two_points_pct IS NOT NULL;
WITH per_day AS ( SELECT h_rank AS lvl, DATE(scheduled_date) AS d, COUNT(*) AS cnt FROM NCAA_INSIGHTS.NCAA_MBB_GAMES_SR WHERE CAST(scheduled_date AS DATETIME) >= '2015-01-01 00:00:00' AND CAST(scheduled_date AS DATETIME) < '2016-01-01 00:00:00' GROUP BY h_rank, DATE(scheduled_date) ) SELECT lvl, d, cnt, SUM(cnt) OVER (PARTITION BY lvl ORDER BY d ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_cnt FROM per_day ORDER BY lvl, d;
WITH cell AS ( SELECT tournament_type AS topic, h_rank AS lvl, COUNT(*) AS cnt FROM NCAA_INSIGHTS.NCAA_MBB_GAMES_SR GROUP BY tournament_type, h_rank ), topic_total AS ( SELECT topic, SUM(cnt) AS total FROM cell GROUP BY topic ), ranked AS ( SELECT c.topic, c.lvl, c.cnt, t.total, CAST(c.cnt AS DOUBLE) / NULLIF(t.total, 0) AS share, ROW_NUMBER() OVER (PARTITION BY c.topic ORDER BY c.cnt DESC) AS rn FROM cell c JOIN topic_total t ON c.topic = t.topic ) SELECT topic, lvl, cnt, share FROM ranked WHERE rn = 1 AND share >= 0.5 ORDER BY share DESC;
SELECT event_id FROM NCAA_INSIGHTS.NCAA_MBB_PBP_SR WHERE event_description LIKE '%offensive rebound%' LIMIT 5;
SELECT conf_name, SUM(CASE WHEN CAST(scheduled_date AS DATETIME) >= '2015-01-01 00:00:00' AND CAST(scheduled_date AS DATETIME) < '2016-01-01 00:00:00' THEN 1 ELSE 0 END) AS curr_cnt, SUM(CASE WHEN CAST(scheduled_date AS DATETIME) >= '2014-01-01 00:00:00' AND CAST(scheduled_date AS DATETIME) < '2015-01-01 00:00:00' THEN 1 ELSE 0 END) AS prev_cnt, ( SUM(CASE WHEN CAST(scheduled_date AS DATETIME) >= '2015-01-01 00:00:00' AND CAST(scheduled_date AS DATETIME) < '2016-01-01 00:00:00' THEN 1 ELSE 0 END) - SUM(CASE WHEN CAST(scheduled_date AS DATETIME) >= '2014-01-01 00:00:00' AND CAST(scheduled_date AS DATETIME) < '2015-01-01 00:00:00' THEN 1 ELSE 0 END) ) AS delta_cnt FROM NCAA_INSIGHTS.NCAA_MBB_PLAYERS_GAMES_SR GROUP BY conf_name ORDER BY delta_cnt DESC LIMIT 3;
SELECT opp_id, SUM(CASE WHEN win = True THEN 1 ELSE 0 END) AS hit_cnt, COUNT(*) AS total_cnt, SUM(CASE WHEN win = True THEN 1 ELSE 0 END) / COUNT(*) AS hit_ratio FROM NCAA_INSIGHTS.NCAA_MBB_HISTORICAL_TEAMS_GAMES GROUP BY opp_id HAVING COUNT(*) >= 20 ORDER BY hit_ratio DESC LIMIT 10;
SELECT type, COUNT(*) AS event_cnt FROM NCAA_INSIGHTS.NCAA_MBB_PBP_SR WHERE CAST(scheduled_date AS DATETIME) >= '2015-01-01 00:00:00' AND CAST(scheduled_date AS DATETIME) < '2016-01-01 00:00:00' AND event_description LIKE '%three point%' GROUP BY type ORDER BY event_cnt DESC LIMIT 5;
SELECT venue_city, type, COUNT(*) AS event_cnt FROM NCAA_INSIGHTS.NCAA_MBB_PBP_SR GROUP BY venue_city, type ORDER BY event_cnt DESC LIMIT 10;
